//! The event entity of the `events` resource, generated by
//! `forge generate scaffold`. Business rules only: no HTTP, SQL or runtime
//! types, so the rules are unit-testable and shared by every adapter.

use std::fmt;

use forge::core::{Id, Timestamp, Uuid, Version};

/// Identifier of a [`Event`]: a typed UUIDv7 generated in Rust, never by
/// the database.
pub type EventId = Id<Event>;

/// Maximum length, in characters, of a `string` field.
pub const STRING_MAX_CHARS: usize = 255;

/// Maximum length, in characters, of a `text` field.
pub const TEXT_MAX_CHARS: usize = 65_535;

/// The values a event is made of. [`Event`] only holds values that pass
/// [`EventAttributes::validate`].
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct EventAttributes {
    pub name: String,
    pub notes: Option<String>,
    pub starts_at: Timestamp,
    pub ends_at: Option<Timestamp>,
    pub capacity: i64,
    pub attendees: Option<i64>,
    pub public: bool,
    pub featured: Option<bool>,
    pub venue: Uuid,
    pub organizer: Option<Uuid>,
}

impl EventAttributes {
    /// Checks every business rule and reports all violations at once.
    pub fn validate(&self) -> Result<(), EventValidationErrors> {
        let mut errors = EventValidationErrors::default();
        check_text(&mut errors, EventField::Name, &self.name, STRING_MAX_CHARS);
        if let Some(value) = &self.notes {
            check_text(&mut errors, EventField::Notes, value, TEXT_MAX_CHARS);
        }
        errors.into_result()
    }
}

/// Text must not be blank and must fit `max` characters.
fn check_text(errors: &mut EventValidationErrors, field: EventField, value: &str, max: usize) {
    if value.trim().is_empty() {
        errors.push(field, EventViolation::Blank);
    } else if value.chars().count() > max {
        errors.push(field, EventViolation::TooLong { max });
    }
}

/// A event: an identity, an optimistic-locking version and valid
/// attributes.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct Event {
    id: EventId,
    version: Version,
    attributes: EventAttributes,
}

impl Event {
    /// A new event with a fresh UUIDv7 and the initial version.
    pub fn new(attributes: EventAttributes) -> Result<Self, EventValidationErrors> {
        Self::restore(EventId::new(), Version::INITIAL, attributes)
    }

    /// A event read from storage or about to replace a stored one,
    /// validated like a new one.
    pub fn restore(
        id: EventId,
        version: Version,
        attributes: EventAttributes,
    ) -> Result<Self, EventValidationErrors> {
        attributes.validate()?;
        Ok(Self {
            id,
            version,
            attributes,
        })
    }

    /// The same event at `version`, after storage accepted a change.
    #[must_use]
    pub fn with_version(self, version: Version) -> Self {
        Self { version, ..self }
    }

    #[must_use]
    pub fn id(&self) -> EventId {
        self.id
    }

    /// The optimistic-locking version: an update or delete must present it.
    #[must_use]
    pub fn version(&self) -> Version {
        self.version
    }

    #[must_use]
    pub fn attributes(&self) -> &EventAttributes {
        &self.attributes
    }

    #[must_use]
    pub fn name(&self) -> &str {
        &self.attributes.name
    }

    #[must_use]
    pub fn notes(&self) -> Option<&str> {
        self.attributes.notes.as_deref()
    }

    #[must_use]
    pub fn starts_at(&self) -> Timestamp {
        self.attributes.starts_at
    }

    #[must_use]
    pub fn ends_at(&self) -> Option<Timestamp> {
        self.attributes.ends_at
    }

    #[must_use]
    pub fn capacity(&self) -> i64 {
        self.attributes.capacity
    }

    #[must_use]
    pub fn attendees(&self) -> Option<i64> {
        self.attributes.attendees
    }

    #[must_use]
    pub fn public(&self) -> bool {
        self.attributes.public
    }

    #[must_use]
    pub fn featured(&self) -> Option<bool> {
        self.attributes.featured
    }

    #[must_use]
    pub fn venue(&self) -> Uuid {
        self.attributes.venue
    }

    #[must_use]
    pub fn organizer(&self) -> Option<Uuid> {
        self.attributes.organizer
    }
}

/// A field of [`EventAttributes`].
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum EventField {
    Name,
    Notes,
    StartsAt,
    EndsAt,
    Capacity,
    Attendees,
    Public,
    Featured,
    Venue,
    Organizer,
}

impl EventField {
    /// The field's name in forms and storage.
    #[must_use]
    pub const fn name(self) -> &'static str {
        match self {
            Self::Name => "name",
            Self::Notes => "notes",
            Self::StartsAt => "starts_at",
            Self::EndsAt => "ends_at",
            Self::Capacity => "capacity",
            Self::Attendees => "attendees",
            Self::Public => "public",
            Self::Featured => "featured",
            Self::Venue => "venue",
            Self::Organizer => "organizer",
        }
    }
}

/// A broken business rule.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum EventViolation {
    /// The value is empty or only whitespace.
    Blank,
    /// The value has more than `max` characters.
    TooLong { max: usize },
}

impl fmt::Display for EventViolation {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Blank => formatter.write_str("can't be blank"),
            Self::TooLong { max } => write!(formatter, "is too long (at most {max} characters)"),
        }
    }
}

/// Every broken rule of a event, in field order.
#[derive(Clone, Debug, Default, Eq, PartialEq)]
pub struct EventValidationErrors {
    violations: Vec<(EventField, EventViolation)>,
}

impl EventValidationErrors {
    /// Records that `field` breaks a rule.
    pub fn push(&mut self, field: EventField, violation: EventViolation) {
        self.violations.push((field, violation));
    }

    /// Whether no rule is broken.
    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.violations.is_empty()
    }

    /// The first violation of `field`.
    #[must_use]
    pub fn get(&self, field: EventField) -> Option<EventViolation> {
        self.violations
            .iter()
            .find(|(candidate, _)| *candidate == field)
            .map(|(_, violation)| *violation)
    }

    /// Every violation in the order it was found.
    pub fn iter(&self) -> impl Iterator<Item = (EventField, EventViolation)> + '_ {
        self.violations.iter().copied()
    }

    /// `Ok` when no rule is broken.
    pub fn into_result(self) -> Result<(), Self> {
        if self.is_empty() { Ok(()) } else { Err(self) }
    }
}

impl fmt::Display for EventValidationErrors {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str("event is invalid")?;
        for (index, (field, violation)) in self.violations.iter().enumerate() {
            let separator = if index == 0 { ": " } else { ", " };
            write!(formatter, "{separator}{} {violation}", field.name())?;
        }
        Ok(())
    }
}

impl std::error::Error for EventValidationErrors {}

#[cfg(test)]
mod tests {
    use super::*;

    fn valid() -> EventAttributes {
        EventAttributes {
            name: "Example name".to_owned(),
            notes: Some("Example notes".to_owned()),
            starts_at: Timestamp::UNIX_EPOCH,
            ends_at: Some(Timestamp::UNIX_EPOCH),
            capacity: 42,
            attendees: Some(42),
            public: true,
            featured: Some(true),
            venue: Uuid::from_u128(0x67e5_5044_10b1_426f_9247_bb68_0e5f_e0c8),
            organizer: Some(Uuid::from_u128(0x67e5_5044_10b1_426f_9247_bb68_0e5f_e0c8)),
        }
    }

    #[test]
    fn new_events_get_a_uuidv7_and_the_initial_version() {
        let created = Event::new(valid());

        let Ok(entity) = created else {
            panic!("valid attributes must be accepted: {created:?}");
        };
        assert_eq!(entity.id().as_uuid().get_version_num(), 7);
        assert_eq!(entity.version(), Version::INITIAL);
        assert_eq!(entity.attributes(), &valid());
    }

    #[test]
    fn blank_and_too_long_text_is_rejected_with_every_violation() {
        let mut attributes = valid();
        attributes.name = "x".repeat(STRING_MAX_CHARS + 1);
        attributes.notes = Some(" ".to_owned());

        let Err(errors) = Event::new(attributes) else {
            panic!("blank and too long values must be rejected");
        };
        assert_eq!(
            errors.get(EventField::Name),
            Some(EventViolation::TooLong {
                max: STRING_MAX_CHARS
            })
        );
        assert_eq!(errors.get(EventField::Notes), Some(EventViolation::Blank));
    }

    #[test]
    fn restore_validates_and_with_version_keeps_the_identity() -> Result<(), EventValidationErrors>
    {
        let entity = Event::new(valid())?;
        let restored = Event::restore(entity.id(), entity.version(), valid())?;
        assert_eq!(restored, entity);

        let Ok(next) = Version::INITIAL.next() else {
            panic!("version 2 exists");
        };
        let moved = restored.with_version(next);
        assert_eq!(moved.id(), entity.id());
        assert_eq!(moved.version().get(), 2);
        Ok(())
    }
}
